mapper.select:
SELECT COUNT(1)
FROM `user_role` ur
         INNER JOIN `role` r
                    ON r.id = ur.role_id
                        AND r.tenant_id = #{tenantId}
                        AND r.status = 1
                        AND r.is_delete = 0
WHERE ur.tenant_id = #{tenantId}
  AND ur.user_id = #{userId}
  AND ur.status = 1
  AND ur.is_delete = 0
  AND r.code = #{roleCode}
